#include <random>
#include <cstdio>
#include <cstring>
const char* target = "ARRRRRARRAAAAAAAARRR";
void try_map(unsigned long long seed, int mode, int skip, const char* name){
    std::mt19937_64 g(seed);
    for (int i = 0; i < skip; ++i) g();
    char buf[21];
    for (int i = 0; i < 20; ++i) {
        unsigned long long x = g();
        double u = (x>>11) * (1.0/9007199254740992.0);
        int bit;
        switch(mode){
            case 0: bit = u < 0.5; break;
            case 1: bit = x & 1; break;
            case 2: bit = x % 2; break;
            case 3: bit = (int)(u*2.0); break;
            case 4: bit = (x>>11)&1; break;
            case 5: bit = (x>>63); break;
            default: bit = 0;
        }
        buf[i] = bit ? 'R' : 'A';  // bit0 -> first allele A
        if (mode==6) buf[i] = 0;
    }
    buf[20]=0;
    if (strcmp(buf,target)==0) printf("MATCH seed=%llu mode=%d skip=%d (%s)\n", seed, mode, skip, name);
}
int main(){
    for (unsigned long long seed = 0; seed < 200000; ++seed)
        for (int mode = 0; mode < 6; ++mode)
            for (int skip = 0; skip < 3; ++skip)
                try_map(seed, mode, skip, "");
    printf("done\n");
    return 0;
}
