#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
std::string target = "ARRRRARGGGGRRRGGRARRARARRARGGARRRRARRRGA";
int main(){
    long d[200];
    srand48(1);
    for (int i = 0; i < 200; ++i) d[i] = lrand48() & 1;
    // try: offset k, 2 draws per pos, allele mapping inv, merge
    for (int k = 0; k < 5; ++k) for (int inv = 0; inv < 2; ++inv) {
        std::string buf;
        for (int i = 0; i < 40; ++i) {
            long a = d[k+2*i], b = d[k+2*i+1];
            if (inv) { a ^= 1; b ^= 1; }
            char ca = a ? 'G' : 'A', cb = b ? 'G' : 'A';
            buf += (ca==cb) ? ca : 'R';
        }
        if (buf == target) printf("MATCH offset=%d inv=%d (2draw merge)\n", k, inv);
    }
    // try: 1 draw decides 'resolve or keep', second picks allele
    for (int k = 0; k < 5; ++k) for (int m = 0; m < 4; ++m) {
        std::string buf;
        for (int i = 0; i < 40; ++i) {
            long a = d[k+2*i], b = d[k+2*i+1];
            char c;
            switch(m){
                case 0: c = a ? (b?'G':'A') : 'R'; break;
                case 1: c = a ? 'R' : (b?'G':'A'); break;
                case 2: c = a ? (b?'A':'G') : 'R'; break;
                default: c = a ? 'R' : (b?'A':'G'); break;
            }
            buf += c;
        }
        if (buf == target) printf("MATCH offset=%d mode=%d (keep/pick)\n", k, m);
    }
    printf("done\n");
}
